def loadMappings(self) -> None:
    basename = os.path.basename(self.mappingsUrl)
    self.modelManager.cntlr.showStatus(_("parsing {0}").format(basename))
    try:
        xmldoc = etree.parse(self.mappingsUrl)
        xmldoc.xinclude()
        for elt in xmldoc.iter(tag="mapFile"):
            self.mappedFiles[elt.get("from")] = elt.get("to")  # type: ignore[index,assignment]
        for elt in xmldoc.iter(tag="mapPath"):
            self.mappedPaths.append((elt.get("from"), elt.get("to")))  # type: ignore[arg-type]
    except (EnvironmentError,
            etree.LxmlError) as err:
        self.modelManager.cntlr.addToLog(_('Disclosure System "%(name)s" import %(importFile)s, error: %(error)s'),
                                         messageCode="arelle:disclosureSystemImportError",
                                         messageArgs={"error": str(err), "name": self.name, "importFile": basename},
                                         level=logging.ERROR)
        etree.clear_error_log()

def mappedUrl(self, url: str) -> str:
    if url in self.mappedFiles:
        mappedUrl = self.mappedFiles[url]
    else:  # handle mapped paths
        mappedUrl = url
        for mapFrom, mapTo in self.mappedPaths:
            if url.startswith(mapFrom):
                mappedUrl = mapTo + url[len(mapFrom):]
                break
    return mappedUrl

def isMappedUrl(self, url: str) -> bool:
    if url in self.mappedFiles:
        return True
    else:  # handle mapped paths
        for mapFrom, mapTo in self.mappedPaths:
            if url.startswith(mapFrom):
                return True
    return False

def encoding(xml: str | bytes, default: str = "utf-8") -> str:
    if isinstance(xml,bytes):
        s = xml[0:120]
        if s.startswith(b"\xef\xbb\xbf"):
            return "utf-8-sig"
        if s.startswith(b"\xff\xfe"):
            return "utf-16"
        if s.startswith(b"\xfe\xff"):
            return "utf-16"
        if s.startswith(b"\xff\xfe\x00\x00"):
            return "utf-32"
        if s.startswith(b"\x00\x00\xfe\xff"):
            return "utf-32"
        if s.startswith(b"# -*- coding: utf-8 -*-"):
            return "utf-8"  # python utf=encoded
        if b"x\0m\0l" in s:
            str = s.decode("utf-16")
        else:
            str = s.decode("latin-1")
    else:
        str = xml[0:80]
    match = xmlEncodingPattern.match(str)
    if match and match.lastindex == 1:
        return match.group(1)
    return default

def loadSchemalocatedSchema(modelXbrl: ModelXbrl, element: ModelObject, relativeUrl: str, namespace: str, baseUrl: str) -> ModelDocument | None:
    if namespace == XbrlConst.xhtml: # block loading xhtml as a schema (e.g., inline which is xsd validated instead)
        return None
    doc = load(modelXbrl, relativeUrl, isIncluded=False, isDiscovered=False, namespace=namespace, referringElement=element, base=baseUrl)
    if doc:
        if doc.targetNamespace != namespace:
            modelXbrl.error("xmlSchema1.4.2.3:refSchemaNamespace",
                _("SchemaLocation of %(fileName)s expected namespace %(namespace)s found targetNamespace %(targetNamespace)s"),
                modelObject=element, fileName=baseUrl,
                namespace=namespace, targetNamespace=doc.targetNamespace)
        else:
            doc.inDTS = False
    return doc

